import{_ as a,a as t,c as i,ac as r}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"人间世 第一季","description":"镜头进入医院，跟随患者、家属与医护人员面对治疗、等待和生死之间的重大选择。节目既记录专业工作的紧张，也呈现普通家庭如何在有限信息、经济压力与情感牵挂中作决定。","frontmatter":{"title":"人间世 第一季","description":"镜头进入医院，跟随患者、家属与医护人员面对治疗、等待和生死之间的重大选择。节目既记录专业工作的紧张，也呈现普通家庭如何在有限信息、经济压力与情感牵挂中作决定。","media":{"category":"documentaries","year":2016,"doubanRating":9.7,"ratingCheckedAt":"2026-10-31","ratingSource":"https://www.bilibili.com/bangumi/play/ss39247","ratingSourceType":"平台转引"},"showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"影视导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"影视 · 纪录片","summary":"镜头进入医院，跟随患者、家属与医护人员面对治疗、等待和生死之间的重大选择。节目既记录专业工作的紧张，也呈现普通家庭如何在有限信息、经济压力与情感牵挂中作决定。","status":"active","related":[{"title":"地球脉动 第二季","link":"/life/personal/media/documentaries/planet-earth-2","kind":"影视导读","scope":"general","audience":"general"},{"title":"蓝色星球 第二季","link":"/life/personal/media/documentaries/blue-planet-2","kind":"影视导读","scope":"general","audience":"general"},{"title":"猎捕","link":"/life/personal/media/documentaries/the-hunt","kind":"影视导读","scope":"general","audience":"general"},{"title":"河西走廊","link":"/life/personal/media/documentaries/hexi-corridor","kind":"影视导读","scope":"general","audience":"general"},{"title":"冰冻星球 第一季","link":"/life/personal/media/documentaries/frozen-planet-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"七个世界，一个星球","link":"/life/personal/media/documentaries/seven-worlds-one-planet","kind":"影视导读","scope":"general","audience":"general"},{"title":"宇宙时空之旅","link":"/life/personal/media/documentaries/cosmos-a-spacetime-odyssey","kind":"影视导读","scope":"general","audience":"general"},{"title":"人类星球","link":"/life/personal/media/documentaries/human-planet","kind":"影视导读","scope":"general","audience":"general"},{"title":"我们的星球 第一季","link":"/life/personal/media/documentaries/our-planet-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"绿色星球","link":"/life/personal/media/documentaries/the-green-planet","kind":"影视导读","scope":"general","audience":"general"},{"title":"生命故事","link":"/life/personal/media/documentaries/life-story","kind":"影视导读","scope":"general","audience":"general"},{"title":"生命（2009）","link":"/life/personal/media/documentaries/life-2009","kind":"影视导读","scope":"general","audience":"general"},{"title":"完美星球","link":"/life/personal/media/documentaries/a-perfect-planet","kind":"影视导读","scope":"general","audience":"general"},{"title":"王朝 第一季","link":"/life/personal/media/documentaries/dynasties-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"舌尖上的中国 第一季","link":"/life/personal/media/documentaries/a-bite-of-china-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"我在故宫修文物（剧集版）","link":"/life/personal/media/documentaries/masters-in-the-forbidden-city","kind":"影视导读","scope":"general","audience":"general"}],"prev":{"text":"生命故事","link":"/life/personal/media/documentaries/life-story"},"next":{"text":"生命（2009）","link":"/life/personal/media/documentaries/life-2009"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"生命故事","link":"/life/personal/media/documentaries/life-story"},"next":{"text":"生命（2009）","link":"/life/personal/media/documentaries/life-2009"}},"headers":[],"relativePath":"life/personal/media/documentaries/life-matters-season-1.md","filePath":"life/personal/media/documentaries/life-matters-season-1.md"}'),n={name:"life/personal/media/documentaries/life-matters-season-1.md"};function l(o,e,d,s,p,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="人间世-第一季" tabindex="-1">人间世 第一季 <a class="header-anchor" href="#人间世-第一季" aria-label="Permalink to &quot;人间世 第一季&quot;">​</a></h1><p><a href="./../overview">影视总览</a> · <a href="./overview">纪录片片单</a></p><h2 id="基本资料" tabindex="-1">基本资料 <a class="header-anchor" href="#基本资料" aria-label="Permalink to &quot;基本资料&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>信息</th></tr></thead><tbody><tr><td>原名 / 别名</td><td>人间世</td></tr><tr><td>年份 / 地区</td><td>2016 / 中国大陆</td></tr><tr><td>类型</td><td>医疗纪实 / 社会 / 生命</td></tr><tr><td>导演 / 主创</td><td>上海广播电视台团队；周全等主创</td></tr><tr><td>篇幅 / 版本</td><td>10 集，单集约 45 分钟</td></tr><tr><td>豆瓣参考评分</td><td><strong>9.7 / 10</strong></td></tr><tr><td>评分依据</td><td><a href="https://www.bilibili.com/bangumi/play/ss39247" target="_blank" rel="noopener noreferrer">哔哩哔哩正版节目页预告文案中的豆瓣评分</a>（平台转引）</td></tr><tr><td>查询日期</td><td>2026-10-31</td></tr></tbody></table><p>评分为公开资料转引或历史快照，已于本次查询核对来源文字，未核实豆瓣实时值；来源时间与查询日期不是同一概念。 篇幅按常见版本作近似说明，片头、花絮及剪辑差异可能影响播放时长。</p><h2 id="创作背景与资料" tabindex="-1">创作背景与资料 <a class="header-anchor" href="#创作背景与资料" aria-label="Permalink to &quot;创作背景与资料&quot;">​</a></h2><p>第一季由新闻团队进入医院长期观察，以十集讨论人与疾病、医护和社会的关系。导演周全在<a href="https://guangdianyanjiu.smgtech.net/e/action/ShowInfo.php?classid=14&amp;id=47" target="_blank" rel="noopener noreferrer">《在医院，我们如何阅读社会》</a>中解释了从医学事件转向人的处境的创作方向；<a href="https://www.xinhuamed.com.cn/news/news-4022.html" target="_blank" rel="noopener noreferrer">新华医院主创讲座记录</a>也保留了这一说明。</p><p>这能解释片中为什么并不只挑选成功救治：等待、沟通和无法逆转的结果，都属于医院里真实发生的生活。本页讨论第一季，后来的第二季及电影版应分别观看和评价。</p><h2 id="内容介绍" tabindex="-1">内容介绍 <a class="header-anchor" href="#内容介绍" aria-label="Permalink to &quot;内容介绍&quot;">​</a></h2><p>镜头进入医院，跟随患者、家属与医护人员面对治疗、等待和生死之间的重大选择。节目既记录专业工作的紧张，也呈现普通家庭如何在有限信息、经济压力与情感牵挂中作决定。</p><p>它没有把医院只拍成奇迹发生的地方，也保留治疗的边界与无法挽回的失去。人与人之间怎样解释、陪伴和告别，成为与医学技术同样重要的内容。</p><h2 id="特色与看点" tabindex="-1">特色与看点 <a class="header-anchor" href="#特色与看点" aria-label="Permalink to &quot;特色与看点&quot;">​</a></h2><h3 id="_1-观察视角" tabindex="-1">1. 观察视角 <a class="header-anchor" href="#_1-观察视角" aria-label="Permalink to &quot;1. 观察视角&quot;">​</a></h3><p>可以留意沟通发生在什么时刻、双方知道哪些信息，以及一句解释为什么可能对家属很重要。理解处境比把人物迅速归为负责或不负责更有帮助。</p><h3 id="_2-表达与理解" tabindex="-1">2. 表达与理解 <a class="header-anchor" href="#_2-表达与理解" aria-label="Permalink to &quot;2. 表达与理解&quot;">​</a></h3><p>记录的具体病例不能代表所有疾病和医院，也不应被拿来预测自己的诊疗结果。它的价值主要在于让平时不易看见的劳动、照护与抉择进入公共视野。</p><h2 id="从具体篇章理解主题" tabindex="-1">从具体篇章理解主题 <a class="header-anchor" href="#从具体篇章理解主题" aria-label="Permalink to &quot;从具体篇章理解主题&quot;">​</a></h2><p>开篇《救命》让观众面对抢救的紧迫与结果的不确定，《理解》把视线移向急救中的沟通，《告别》则进入临终关怀。<a href="https://media.people.com.cn/n1/2016/0706/c40606-28527639.html" target="_blank" rel="noopener noreferrer">当年的主创采访报道</a>可补充这些篇章的拍摄背景。它们连起来，形成从“能做什么”到“无法治愈时还能怎样陪伴”的问题线索。</p><p>建议每次只看一集，尤其不要连续把所有沉重情节当作情绪冲击消费。留意一个故事中信息何时被说明、谁在等待、谁承担决定，会比只记住最后的成败更接近作品的关怀。</p><h2 id="医护、患者与家属的不同时间" tabindex="-1">医护、患者与家属的不同时间 <a class="header-anchor" href="#医护、患者与家属的不同时间" aria-label="Permalink to &quot;医护、患者与家属的不同时间&quot;">​</a></h2><p>对医护而言，某个流程可能每天重复；对第一次经历重大疾病的家庭，那可能是生命中最陌生的时刻。同样几分钟，一边意味着任务排序，一边可能被体验为漫长的无助。片中的冲突经常由这种时间与知识差异放大。</p><p>患者也并非只是等待处理的病例。病痛、牵挂、尊严与家庭责任会共同影响表达和选择。观看时可以把专业行为与个人处境并排理解，而不急于用结果给每个人的品格打分；结果未能如愿，也不等于过程中的照护毫无价值。</p><h2 id="观察式拍摄与伦理边界" tabindex="-1">观察式拍摄与伦理边界 <a class="header-anchor" href="#观察式拍摄与伦理边界" aria-label="Permalink to &quot;观察式拍摄与伦理边界&quot;">​</a></h2><p>长时间跟随让镜头能够记录犹豫、沉默和关系变化，现场声音保留了大量难以由事后访谈重建的压力。但成片仍经过选择，观众看到的是部分时间、部分人物和特定主题，不能据此推断所有医院或所有患者的经历。</p><p>真实病痛具有强烈情绪力量，也要求观看者尊重被摄者。可以讨论制度、沟通和照护，却不宜把脆弱时刻截成嘲讽素材，更不能把个别病例当作自己的诊疗预测。本片最有意义的观看收获，是增加对他人处境的耐心，而不是制造对医院的单一想象。</p><h2 id="适合谁看与观看建议" tabindex="-1">适合谁看与观看建议 <a class="header-anchor" href="#适合谁看与观看建议" aria-label="Permalink to &quot;适合谁看与观看建议&quot;">​</a></h2><p>适合关心社会现实、照护关系与生命议题的人。包含真实抢救、病痛、死亡和悲伤，建议按情绪承受情况分次观看；不是面向患者的医疗教程。</p><h2 id="看后思考" tabindex="-1">看后思考 <a class="header-anchor" href="#看后思考" aria-label="Permalink to &quot;看后思考&quot;">​</a></h2><p>当无法保证理想结果时，专业照护还能提供什么？家属与医护之间有哪些容易被忽略的信息差？</p><p>创作事实见段落所附来源；人物、场景与评价部分为本站观影分析，不代表主创唯一解释。正文保留主要故事体验，不展开关键结局。评分用于辅助选片，不代表每位观众的感受。</p><h2 id="资料与复核入口" tabindex="-1">资料与复核入口 <a class="header-anchor" href="#资料与复核入口" aria-label="Permalink to &quot;资料与复核入口&quot;">​</a></h2><ul><li><a href="https://www.bilibili.com/bangumi/play/ss39247" target="_blank" rel="noopener noreferrer">哔哩哔哩正版节目页预告文案中的豆瓣评分</a>：本页评分依据；查询于 2026-10-31。</li></ul><p><a href="./overview">返回纪录片片单</a> · <a href="./../overview">返回影视总览</a></p>',33)])])}const u=a(n,[["render",l]]);export{m as __pageData,u as default};
